import { useState, useEffect } from "react"

export default function Quote(){
  const [quote, setQuote] = useState("")
  const [author, setAuthor] = useState("") 
  useEffect(()=>{

       fetch("https://zenquotes.io/api/random")
        .then((resp) => resp.json) 
        .then((data) => {
        setQuote(data[0].q)
        setAuthor(data[0].a)
      })


  },[])
  return (
    <div class="container">
      <div class="quote">
        {{quote}}
      </div>
      <div class="author">
        — {{author}} 
      </div>
    </div>
  )
}
